internal import GRDB

/// A typed column generated by `@Table`.
public struct TableColumn<Value: Sendable>: Sendable {
    public let name: String

    public init(_ name: String) {
        self.name = name
    }

    public var asc: TableOrder { TableOrder(GRDB.Column(name).asc) }
    public var desc: TableOrder { TableOrder(GRDB.Column(name).desc) }
}

public struct TablePredicate: Sendable {
    let expression: SQLExpression

    public static func && (lhs: Self, rhs: Self) -> Self {
        Self(expression: lhs.expression && rhs.expression)
    }

    public static func || (lhs: Self, rhs: Self) -> Self {
        Self(expression: lhs.expression || rhs.expression)
    }

    public static prefix func ! (operand: Self) -> Self {
        Self(expression: !operand.expression)
    }
}

public struct TableOrder: Sendable {
    let orderings: [SQLOrdering]

    init(_ ordering: SQLOrdering) {
        self.orderings = [ordering]
    }

    private init(_ orderings: [SQLOrdering]) {
        self.orderings = orderings
    }

    /// Composes stable ordering, e.g. `updatedAt.desc.then(sequence.desc)`.
    public func then(_ other: TableOrder) -> TableOrder {
        TableOrder(orderings + other.orderings)
    }

    static func combined(_ orders: [TableOrder]) -> TableOrder {
        TableOrder(orders.flatMap(\.orderings))
    }
}

// MARK: - Comparison operators

public func == <Value: SQLValueConvertible & Sendable>(lhs: TableColumn<Value>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) == rhs.sqlValue.databaseValue)
}

public func != <Value: SQLValueConvertible & Sendable>(lhs: TableColumn<Value>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) != rhs.sqlValue.databaseValue)
}

public func < <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) < rhs.sqlValue.databaseValue)
}

public func <= <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) <= rhs.sqlValue.databaseValue)
}

public func > <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) > rhs.sqlValue.databaseValue)
}

public func >= <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) >= rhs.sqlValue.databaseValue)
}

public func == <Value: SQLValueConvertible & Sendable>(lhs: TableColumn<Value?>, rhs: Value?) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) == rhs.sqlValue.databaseValue)
}

public func != <Value: SQLValueConvertible & Sendable>(lhs: TableColumn<Value?>, rhs: Value?) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) != rhs.sqlValue.databaseValue)
}

public func < <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value?>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) < rhs.sqlValue.databaseValue)
}

public func <= <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value?>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) <= rhs.sqlValue.databaseValue)
}

public func > <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value?>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) > rhs.sqlValue.databaseValue)
}

public func >= <Value: SQLValueConvertible & Comparable & Sendable>(lhs: TableColumn<Value?>, rhs: Value) -> TablePredicate {
    TablePredicate(expression: GRDB.Column(lhs.name) >= rhs.sqlValue.databaseValue)
}

// MARK: - Column predicates

extension TableColumn where Value: SQLValueConvertible {
    /// Matches rows whose column value is contained in `values`.
    public func `in`<S: Sequence>(_ values: S) -> TablePredicate where S.Element == Value {
        let dbValues = values.map { $0.sqlValue.databaseValue }
        return TablePredicate(expression: dbValues.contains(GRDB.Column(name)))
    }
}

public protocol OptionalColumnValue: Sendable {
    associatedtype WrappedValue: SQLValueConvertible & Sendable
}

extension Optional: OptionalColumnValue where Wrapped: SQLValueConvertible & Sendable {
    public typealias WrappedValue = Wrapped
}

extension TableColumn where Value: OptionalColumnValue {
    public var isNull: TablePredicate {
        TablePredicate(expression: GRDB.Column(name) == nil)
    }

    public var isNotNull: TablePredicate {
        TablePredicate(expression: GRDB.Column(name) != nil)
    }

    /// Matches rows whose non-null column value is contained in `values`.
    public func `in`<S: Sequence>(_ values: S) -> TablePredicate where S.Element == Value.WrappedValue {
        let dbValues = values.map { $0.sqlValue.databaseValue }
        return TablePredicate(expression: dbValues.contains(GRDB.Column(name)))
    }
}

extension TableColumn where Value == String {
    /// Literal substring matching; percent, underscore, and backslash are escaped.
    public func contains(_ text: String) -> TablePredicate {
        TablePredicate(expression: GRDB.Column(name).like("%\(escapeLike(text))%", escape: "\\"))
    }

    /// Literal prefix matching; percent, underscore, and backslash are escaped.
    public func hasPrefix(_ prefix: String) -> TablePredicate {
        TablePredicate(expression: GRDB.Column(name).like("\(escapeLike(prefix))%", escape: "\\"))
    }

    /// Literal suffix matching; percent, underscore, and backslash are escaped.
    public func hasSuffix(_ suffix: String) -> TablePredicate {
        TablePredicate(expression: GRDB.Column(name).like("%\(escapeLike(suffix))", escape: "\\"))
    }
}

extension TableColumn where Value == String? {
    /// Literal substring matching on an optional string column.
    public func contains(_ text: String) -> TablePredicate {
        TablePredicate(expression: GRDB.Column(name).like("%\(escapeLike(text))%", escape: "\\"))
    }

    /// Literal prefix matching on an optional string column.
    public func hasPrefix(_ prefix: String) -> TablePredicate {
        TablePredicate(expression: GRDB.Column(name).like("\(escapeLike(prefix))%", escape: "\\"))
    }

    /// Literal suffix matching on an optional string column.
    public func hasSuffix(_ suffix: String) -> TablePredicate {
        TablePredicate(expression: GRDB.Column(name).like("%\(escapeLike(suffix))", escape: "\\"))
    }
}

private func escapeLike(_ text: String) -> String {
    text.replacingOccurrences(of: "\\", with: "\\\\")
        .replacingOccurrences(of: "%", with: "\\%")
        .replacingOccurrences(of: "_", with: "\\_")
}

// MARK: - Query builder

public struct TableQuery<Record: TableModel>: Sendable {
    let writer: any GRDB.DatabaseWriter
    let predicate: TablePredicate?
    let ordering: TableOrder?
    let limitCount: Int?
    let offsetCount: Int?

    init(
        writer: any GRDB.DatabaseWriter,
        predicate: TablePredicate? = nil,
        ordering: TableOrder? = nil,
        limitCount: Int? = nil,
        offsetCount: Int? = nil
    ) {
        self.writer = writer
        self.predicate = predicate
        self.ordering = ordering
        self.limitCount = limitCount
        self.offsetCount = offsetCount
    }

    public func filter(_ makePredicate: (Record.Columns) -> TablePredicate) -> Self {
        let next = makePredicate(Record.columns)
        let combined = predicate.map { $0 && next } ?? next
        return Self(writer: writer, predicate: combined, ordering: ordering, limitCount: limitCount, offsetCount: offsetCount)
    }

    public func orderBy(_ makeOrders: (Record.Columns) -> [TableOrder]) -> Self {
        Self(
            writer: writer,
            predicate: predicate,
            ordering: TableOrder.combined(makeOrders(Record.columns)),
            limitCount: limitCount,
            offsetCount: offsetCount
        )
    }

    public func limit(_ count: Int) -> Self {
        Self(writer: writer, predicate: predicate, ordering: ordering, limitCount: max(0, count), offsetCount: offsetCount)
    }

    public func offset(_ count: Int) -> Self {
        Self(writer: writer, predicate: predicate, ordering: ordering, limitCount: limitCount, offsetCount: max(0, count))
    }

    public func fetch() async throws -> [Record] {
        let predicate = self.predicate
        let ordering = self.ordering
        let limitCount = self.limitCount
        let offsetCount = self.offsetCount
        return try await writer.read { db in
            try Self.request(predicate: predicate, ordering: ordering, limitCount: limitCount, offsetCount: offsetCount)
                .fetchAll(db)
                .map(\.model)
        }
    }

    public func first() async throws -> Record? {
        let predicate = self.predicate
        let ordering = self.ordering
        let limitCount = self.limitCount == 0 ? 0 : 1
        let offsetCount = self.offsetCount
        return try await writer.read { db in
            try Self.request(predicate: predicate, ordering: ordering, limitCount: limitCount, offsetCount: offsetCount)
                .fetchOne(db)?
                .model
        }
    }

    public func count() async throws -> Int {
        let predicate = self.predicate
        let ordering = self.ordering
        let limitCount = self.limitCount
        let offsetCount = self.offsetCount
        return try await writer.read { db in
            try Self.request(predicate: predicate, ordering: ordering, limitCount: limitCount, offsetCount: offsetCount)
                .fetchCount(db)
        }
    }

    public func exists() async throws -> Bool {
        guard limitCount != 0 else { return false }
        return try await first() != nil
    }

    @discardableResult
    public func update(_ changes: (inout TableChanges<Record>) -> Void) async throws -> Int {
        var patch = TableChanges<Record>()
        changes(&patch)
        let assignments = patch.assignments
        let predicate = self.predicate
        let ordering = self.ordering
        let limitCount = self.limitCount
        let offsetCount = self.offsetCount
        return try await writer.write { db in
            try TransactionTable<Record>(
                database: db,
                predicate: predicate,
                ordering: ordering,
                limitCount: limitCount,
                offsetCount: offsetCount
            ).update { _ in assignments }
        }
    }

    @discardableResult
    public func delete() async throws -> Int {
        let predicate = self.predicate
        let ordering = self.ordering
        let limitCount = self.limitCount
        let offsetCount = self.offsetCount
        return try await writer.write { db in
            try TransactionTable<Record>(
                database: db,
                predicate: predicate,
                ordering: ordering,
                limitCount: limitCount,
                offsetCount: offsetCount
            ).delete()
        }
    }

    public func observe() -> TableObservation<Record> {
        let predicate = self.predicate
        let ordering = self.ordering
        let limitCount = self.limitCount
        let offsetCount = self.offsetCount
        let observation = ValueObservation.tracking { db in
            try Self.request(predicate: predicate, ordering: ordering, limitCount: limitCount, offsetCount: offsetCount)
                .fetchAll(db)
                .map(\.model)
        }
        return TableObservation(observation.values(in: writer, bufferingPolicy: .bufferingNewest(1)))
    }

    static func request(
        predicate: TablePredicate?,
        ordering: TableOrder?,
        limitCount: Int?,
        offsetCount: Int?
    ) -> QueryInterfaceRequest<RecordAdapter<Record>> {
        var request = RecordAdapter<Record>.all()
        if let predicate { request = request.filter(predicate.expression) }
        if let ordering { request = request.order(ordering.orderings) }
        if let limitCount {
            request = request.limit(limitCount, offset: offsetCount)
        } else if let offsetCount, offsetCount > 0 {
            request = request.limit(-1, offset: offsetCount)
        }
        return request
    }
}

/// A cancellable asynchronous stream of query snapshots.
public struct TableObservation<Record: TableModel>: AsyncSequence, Sendable {
    public typealias Element = [Record]

    private let base: AsyncValueObservation<[Record]>

    init(_ base: AsyncValueObservation<[Record]>) {
        self.base = base
    }

    public func makeAsyncIterator() -> Iterator {
        Iterator(base.makeAsyncIterator())
    }

    public struct Iterator: AsyncIteratorProtocol {
        private var base: AsyncValueObservation<[Record]>.Iterator

        init(_ base: AsyncValueObservation<[Record]>.Iterator) {
            self.base = base
        }

        public mutating func next() async throws -> [Record]? {
            try await base.next()
        }
    }
}
